// Decide qué versiones consultar al catálogo de Pilot para traer sus especificaciones.
// Una consulta por modelo+versión (las versiones repetidas por año comparten especificaciones).
const MAX_CONSULTAS = 12; // la API de Pilot permite 60 requests por minuto en total

const { buscado, modelos } = $input.first().json;

const vistos = new Map();
for (const m of modelos || []) {
  for (const v of m.versiones || []) {
    const clave = `${m.modelo}|${v.version}`.toUpperCase();
    if (v.codigo && !vistos.has(clave)) vistos.set(clave, v.codigo);
  }
}

// Sin búsqueda concreta (o demasiado amplia): no se piden especificaciones
const consultar = String(buscado || '').trim() !== '' && vistos.size > 0 && vistos.size <= MAX_CONSULTAS;
if (!consultar) return [{ json: { consultar: false } }];

return [...vistos.entries()].map(([clave, codigo]) => ({ json: { consultar: true, clave, codigo } }));

// Une las especificaciones del catálogo de Pilot a cada versión y arma el texto para la IA
const { buscado, modelos } = $('unificar').first().json;
const consultas = $('armar_consultas').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);
const huboConsulta = consultas[0]?.consultar === true;

// 1. Especificaciones por modelo+versión
const specs = {};
if (huboConsulta) {
  consultas.forEach((c, i) => {
    const r = respuestas[i] || {};
    const raw = r.result?.entitydata;
    const prod = Array.isArray(raw) ? (raw[0]?.entitydata ?? raw[0]) : raw;

    if (r.result?.status !== 'success' || !prod) {
      specs[c.clave] = { error: r.result?.message || 'Sin datos en el catálogo' };
      return;
    }

    const grupos = (prod.characteristics || [])
      .map((g) => ({
        grupo: g.name,
        atributos: (g.attributes || [])
          .filter((a) => a.value !== null && a.value !== undefined && String(a.value).trim() !== '')
          .map((a) => ({ nombre: a.name, valor: String(a.value).trim() })),
      }))
      .filter((g) => g.atributos.length);

    const recursos = prod.resources || [];
    const imagenes = recursos
      .filter((x) => x.type === 'image')
      .map((x) => (x.resource || []).find((s) => s.size === 'desktop')?.uri || x.resource?.[0]?.uri)
      .filter(Boolean);
    const videos = recursos.filter((x) => x.type === 'video').map((x) => x.resource?.[0]?.uri).filter(Boolean);

    specs[c.clave] = { grupos, imagenes, videos };
  });
}

// 2. Agregarlas a cada versión
const salida = modelos.map((m) => ({
  ...m,
  versiones: m.versiones.map((v) => {
    const s = specs[`${m.modelo}|${v.version}`.toUpperCase()];
    if (!s) return v;
    return s.error
      ? { ...v, especificaciones: [], especificaciones_error: s.error }
      : { ...v, especificaciones: s.grupos, imagenes_catalogo: s.imagenes, videos: s.videos };
  }),
}));

// 3. Texto compacto para la IA
const cop = (n) => '$' + String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const plural = (n) => `${n} ${n === 1 ? 'versión' : 'versiones'}`;

let texto;
if (!salida.length) {
  texto = `No hay modelos que coincidan con "${buscado}".`;
} else if (!String(buscado || '').trim()) {
  texto = 'Modelos disponibles (elegir uno):\n' +
    salida.map((m) => `- ${m.modelo}: ${plural(m.cantidad_versiones)}, desde ${cop(m.precio_desde)}`).join('\n');
} else {
  texto = salida.map((m) => {
    const cab = `${m.versiones[0]?.marca} ${m.modelo} (${plural(m.cantidad_versiones)})` +
      (m.ficha ? `\nficha: ${m.ficha}` : '');
    const vs = m.versiones.map((v) => {
      const base = [
        `- ${v.version}`,
        `código: ${v.codigo}`,
        `precio lista: ${cop(v.precio_lista)}`,
        v.descuento ? `descuento: ${cop(v.descuento)}` : null,
        `precio final: ${cop(v.precio_final)}`,
        v.imagen ? `imagen: ${v.imagen}` : null,
        v.descripcion ? `descripción: ${v.descripcion.replace(/\s+/g, ' ')}` : null,
      ].filter(Boolean).join(' | ');
      const esp = (v.especificaciones || [])
        .map((g) => `    ${g.grupo}: ` + g.atributos.map((a) => `${a.nombre} ${a.valor}`).join('; '))
        .join('\n');
      return esp ? `${base}\n  Especificaciones:\n${esp}` : base;
    });
    return `${cab}\n${vs.join('\n')}`;
  }).join('\n\n');
}

return [{ json: { buscado, total_modelos: salida.length, texto, modelos: salida } }];

