  'BRONCO SPORT': 'FT%20Bronco%20Sport.pdf',
  'BRONCO':       'FT%20Bronco.pdf',
  'E-TRANSIT':    'FT%20e-Transit%20chasis.pdf',
  'EXPEDITION':   'FT%20Expedition.pdf',
  'EXPLORER':     'FT%20Explorer.pdf',
  'F-150':        'FT%20F-150.pdf',
  'MAVERICK':     'FT%20Maverick_compressed.pdf',
  'MUSTANG':      'FT%20Mustang%20GT%20Premium.pdf',
