  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const limpiarHtml = (html) =>
  String(html || '')
    .replace(/<img[^>]*>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();

const extraerImagen = (html) => {
  const m = String(html || '').match(/<img[^>]+src=["']([^"']+)["']/i);
  return m ? m[1] : '';
};

// 3. Filtrar
const validos = todos.filter((p) => {
  const activo = String(p.visible) === '1' && String(p.deleted) === '0';
  const tipoOk = INCLUIR_FORD_PRO || p.business_type?.code === 'ford_vehiculo';
  return activo && tipoOk;
});

