  },
];

// Filtra el catálogo por el texto recibido en "modelo".
// - Separa el texto en palabras y las compara contra TODOS los campos de cada versión.
// - Si no matchea nada, devuelve todo el catálogo.
const buscado = String($('When Executed by Another Workflow').first().json.modelo ?? '');
const catalogo = $input.first().json.modelos || [];

// minúsculas, sin acentos ni símbolos (F-150 -> f150)
const norm = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '');

const STOP = new Set(['de', 'del', 'la', 'el', 'los', 'las', 'un', 'una', 'y', 'o', 'en', 'con', 'por', 'para',
  'quiero', 'quisiera', 'info', 'informacion', 'sobre', 'me', 'interesa', 'modelo', 'version', 'ford']);

// 1. Palabras de la búsqueda (sin repetidos ni palabras vacías)
let tokens = [...new Set(
  buscado
    .split(/[\s,;]+/)
    .filter((w) => !STOP.has(norm(w)))
    .map(norm)
    .filter((t) => t.length >= 2)
)];

// Texto completo pegado ("f 150" -> "f150"), por si el nombre del modelo tiene símbolos
const completo = norm(buscado.split(/[\s,;]+/).filter((w) => !STOP.has(norm(w))).join(''));
if (completo.length >= 2 && !tokens.includes(completo)) tokens.push(completo);

// 2. Texto de cada campo de cada versión
const campos = (m, v) => ({
  modelo: norm(m.modelo),
  version: norm(`${v.version} ${v.codigo} ${v.nombre_completo}`),
  otros: norm(`${v.marca} ${v.tipo_negocio} ${v.descripcion} ${v.precio_lista} ${v.precio_final}`),
});

const todas = catalogo.flatMap((m) => m.versiones.map((v) => ({ m, v, f: campos(m, v) })));

// Palabras que aparecen en todas las versiones no sirven para buscar (ej: "Ford")
tokens = tokens.filter((t) => !todas.every(({ f }) => f.modelo.includes(t) || f.version.includes(t) || f.otros.includes(t)));

const armar = (lista) => {
  const porModelo = new Map();
  for (const { m, v } of lista) {
    if (!porModelo.has(m.modelo)) porModelo.set(m.modelo, { m, versiones: [] });
    porModelo.get(m.modelo).versiones.push(v);
  }
  return [...porModelo.values()].map(({ m, versiones }) => ({ ...m, cantidad_versiones: versiones.length, versiones }));
};

const salida = (coincidencia, modelos) => [{
  json: { buscado, tokens, coincidencia, total_modelos: modelos.length, modelos },
}];

// Sin palabras útiles: todo el catálogo
if (!tokens.length) return salida('ninguna', catalogo);

// 3. Primero por nombre de modelo (gana el/los modelos que matchean más palabras)
const puntajeModelo = (m) => tokens.filter((t) => norm(m.modelo).includes(t)).length;
const mejorModelo = Math.max(0, ...catalogo.map(puntajeModelo));

if (mejorModelo > 0) {
  const elegidos = catalogo.filter((m) => puntajeModelo(m) === mejorModelo);
  // las palabras que no son del modelo (ej: "xlt", "v6", "platinum") afinan las versiones
  const afinan = tokens.filter((t) => !elegidos.some((m) => norm(m.modelo).includes(t)));

  const lista = [];
  for (const m of elegidos) {
    const puntaje = (v) => afinan.filter((t) => campos(m, v).version.includes(t)).length;
    const mejor = Math.max(0, ...m.versiones.map(puntaje));
    const versiones = mejor > 0 ? m.versiones.filter((v) => puntaje(v) === mejor) : m.versiones;
    versiones.forEach((v) => lista.push({ m, v }));
  }
  return salida('modelo', armar(lista));
}

// 4. Si ningún modelo coincide, se busca en todos los campos (versión, código, descripción, marca, precio...)
const puntaje = ({ f }) => tokens.filter((t) => f.modelo.includes(t) || f.version.includes(t) || f.otros.includes(t)).length;
const mejor = Math.max(0, ...todas.map(puntaje));
if (mejor > 0) return salida('campos', armar(todas.filter((x) => puntaje(x) === mejor)));

// 5. Sin coincidencias: devuelve todo sin importar modelo ni versión
return salida('ninguna', catalogo);
